def parse_host_mask(text):
    """Identify hostmask."""
    argc = len(text)
    if argc >= 2:
        opt = Identifier(text[1])
        mask = opt
        if not opt.is_nick() and argc < 3:
            return None
        if not opt.is_nick():
            mask = text[2]
        if re.match('^[^.@!/]+$', mask) is not None:
            return f'{mask}!*@*'
        if re.match('^[^@!]+$', mask) is not None:
            return f'*!*@{mask}'
        m = re.match('^([^!@]+)@$', mask)
        if m is not None:
            return f'*!{m.group(1)}@*'
        m = re.match('^([^!@]+)@([^@!]+)$', mask)
        if m is not None:
            return f'*!{m.group(1)}@{m.group(2)}'
        m = re.match('^([^!@]+)!(^[!@]+)@?$', mask)
        if m is not None:
            return f'{m.group(1)}!{m.group(2)}@*'
        return ''
    return None
