    try:
        options = re2.Options()
        options.log_errors = False
        re2.compile(value, options=options)
    except re2.error as e:
        if len(e.args) >= 1:
            if isinstance(e.args[0], str):
                raise ValidationError(_("Bad regular expression: {}").format(e.args[0]))
