class PSFile:
    """
    Wrapper for bytesio object that treats either CR or LF as end of line.
    """
class EpsImageFile(ImageFile.ImageFile):
    def _open(self):
        (length, offset) = self._find_offset(self.fp)
        fp = PSFile(self.fp)
        fp.seek(offset)
        box = None
        self.mode = "RGB"
        self._size = 1, 1
        s_raw = fp.readline()
        s = s_raw.strip("\r\n")
        while s_raw:
            if s:
                if len(s) > 255:
                    raise SyntaxError("not an EPS file")
                try:
                    m = split.match(s)
                except re.error as e:
                    raise SyntaxError("not an EPS file") from e
                if m:
                    k, v = m.group(1, 2)
                    self.info[k] = v
                    if k == "BoundingBox":
                        try:
                            box = [int(float(i)) for i in v.split()]
                            self._size = box[2] - box[0], box[3] - box[1]
                            self.tile = [
                                ("eps", (0, 0) + self.size, offset, (length, box))
                            ]
                        except Exception:
                            pass
                else:
                    m = field.match(s)
                    if m:
                        k = m.group(1)
                        if k == "EndComments":
                            break
                        if k[:8] == "PS-Adobe":
                            self.info[k[:8]] = k[9:]
                        else:
                            self.info[k] = ""
                    elif s[0] == "%":
                        pass
                    else:
                        raise OSError("bad EPS header")
            s_raw = fp.readline()
            s = s_raw.strip("\r\n")
            if s and s[:1] != "%":
                break
        while s[:1] == "%":
            if len(s) > 255:
                raise SyntaxError("not an EPS file")
            if s[:11] == "%ImageData:":
                x, y, bi, mo = s[11:].split(None, 7)[:4]
                if int(bi) != 8:
                    break
                try:
                    self.mode = self.mode_map[int(mo)]
                except ValueError:
                    break
                self._size = int(x), int(y)
                return
            s = fp.readline().strip("\r\n")
            if not s:
                break
        if not box:
            raise OSError("cannot determine EPS bounding box")

