    """A QtWebEngine tab in the browser.
    Signals:
        abort_questions: Emitted when a new load started or we're shutting
            down.
    """
    abort_questions = pyqtSignal()
    def url(self, *, requested=False):
        page = self._widget.page()
        if requested:
            return page.requestedUrl()
        else:
            return page.url()
