                        log.warning(
                            "skipping installation of package %s when"
                            " performing an offline install.",
                            package.name,
                        )
                        continue
                    await self.install_package(context=context, package=package.name)
        finally:
            await self.configure_cloud_init(context=context)
        if self.supports_apt():
